def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp_d = sum(1 for h in history if h[1] == 'D')
    my_d = sum(1 for h in history if h[0] == 'D')

    if n == 10 and opp_d == 0 and my_d == 0:
        return 'D'
    if n == 11 and opp_d == 0 and my_d == 1:
        return 'D'
    if n == 12 and opp_d == 0 and my_d == 2:
        return 'C'

    if n >= 13 and history[12][1] == 'C' and opp_d == 0 and my_d >= 2:
        return 'D'

    if n >= 99:
        return 'D'

    opp_rate = opp_d / n
    if opp_rate > 0.5:
        return 'D'

    last_opp = history[-1][1]
    last_my = history[-1][0]

    if last_opp == 'D':
        if opp_rate > 0.3:
            return 'D'
        else:
            return 'C'
    else:
        if last_my == 'D':
            return 'C'
        return 'C'
